def IsProductDiagonal (c : NormalizedSchauderBasis 𝕜 Y)
    (D : SchauderSum b hb Y →L[𝕜] SchauderSum b hb Y) : Prop :=
  ∃ d : ℕ × ℕ → 𝕜, ∀ p, D (productVector c p) = d p • productVector c p

